// -----------------------------------------------------------------------------
// i2s_rx - Philips I2S frame decoder with idle detection
//          (design.md Sec. 2.2.3 port contract, tasks.md T-M0-02)
// -----------------------------------------------------------------------------
// Decodes the 3-wire I2S slave stream (BCK/LRCK generated by i2s_clk_gen,
// SD from the external source) into 16-bit left/right PCM samples at
// 44.1 kHz per channel. ALL logic runs in the clk_nco (216 MHz) domain
// and advances on the bck_tick enable - the module effectively works in
// a virtual 44.1 kHz-family clock domain, so no slow-domain logic and no
// metastability (design.md Sec. 1.2 "audio beat semantics").
//
// SD synchronizer (REQ-AUD-007): i2s_sd is asynchronous to clk_nco; it
// passes through a two-stage sync pipe (sd_meta -> sd_sync, ~9.26 ns
// shift at 216 MHz). The shift is negligible against the I2S bit period
// of 708 ns (half period 354 ns), so sampling sd_sync at the BCK rising
// edge tick still lands well inside the data-bit valid window.
//
// Sample point: the BCK rising edge happens on the tick where bck_phase
// goes even -> odd, so the sample enable is:
//     sample_en = bck_tick & bck_phase[0]
// Both signals are registered by the generator; bck_phase is the NEW
// phase when the receiver consumes the tick one clk_nco cycle later.
//
// Bit-to-phase mapping (Philips I2S, 16-bit compact, MSB first, delayed
// 1 BCK after the LRCK edge - bit-level self-check table):
//   LRCK toggles on the phase 31->0 tick (BCK falling edge). One BCK
//   after the LRCK edge, the transmitter presents the new word MSB, so:
//     bit15 (MSB) sampled at  phase 2 -> 3 tick   (this half frame)
//     bit14 .. bit1 sampled at phase 4->5 .. 30->31 ticks
//     bit0  (LSB) sampled at  phase 0 -> 1 tick   (NEXT half frame)
//   The serial stream is therefore continuous across the frame boundary
//   (the phase 0->1 sample of a half frame is the previous word's LSB),
//   and a plain 16-bit shift register left-shifting on every sample_en
//   captures each word seamlessly: when bit0 is shifted in at post-edge phase==1,
//   sr holds the complete 16-bit word of the PREVIOUS half frame
//   (the frame whose channel level was latched at its MSB sample).
//
// Channel tagging: i2s_lrck is latched at the MSB sample instant
// (phase==3 && sample_en); at that moment lrck already carries the
// current half frame's level. word_ch=0 -> LEFT (pcm_l), 1 -> RIGHT.
//
// Word completion timing (T/T+1 registered output): at the bit0 sample
// cycle (T) the completed word {sr[14:0], sd_sync} is captured into
// word_data; on the next clk_nco cycle (T+1) pcm_l/pcm_r are updated
// and pcm_valid pulses for one cycle. pcm_valid and pcm_l/pcm_r present
// new values in the SAME cycle, so consumers sample them together
// (standard valid/data protocol). Word rate = 88.2 kHz total
// (44.1 kHz per channel).
//
// Idle detection (REQ-REL-003): sd_sync is compared against its 1-cycle
// delayed copy on EVERY clk_nco edge; any transition resets the idle
// tick counter. The counter increments once per bck_tick without a
// transition; after 128 ticks (~45.3 us = 2 LRCK periods, i.e. more
// than the ">1 LRCK period" spec) sd_idle latches high. sd_idle is
// cleared by the first SD transition. Downstream (audio_sink) treats
// sd_idle and abnormal samples as silence so the pipeline keeps running.
//
// Port note: i2s_sd <- pin V16 (LVCMOS33); pin constraints are the
// responsibility of T-M0-09 (instrec_top.fdc).
// -----------------------------------------------------------------------------
module i2s_rx (
    input  wire       clk_nco,    // 216 MHz domain
    input  wire       rst_n,      // clk_nco-domain reset, sync release
    input  wire       i2s_sd,     // raw serial data pin (V16, async)
    input  wire       bck_tick,   // BCK half-period enable from i2s_clk_gen
    input  wire [4:0] bck_phase,  // frame phase 0..31 from i2s_clk_gen
    input  wire       i2s_lrck,   // frame clock level (channel tag source)
    output reg  [15:0] pcm_l,     // left channel sample (LRCK low half frame)
    output reg  [15:0] pcm_r,     // right channel sample (LRCK high half frame)
    output reg        pcm_valid,  // one-cycle pulse per complete 16-bit word
    output reg        sd_idle     // SD line static for >1 LRCK period
);

    // ------------------------------------------------------------------
    // Two-stage synchronizer for the asynchronous SD input (REQ-AUD-007).
    // sd_sync is the contract-level "i2s_sd_sync" signal, generated here
    // so the top level wires the raw pin directly into this module.
    // ------------------------------------------------------------------
    reg sd_meta;
    reg sd_sync;

    always @(posedge clk_nco or negedge rst_n) begin
        if (!rst_n) begin
            sd_meta <= 1'b0;
            sd_sync <= 1'b0;
        end else begin
            sd_meta <= i2s_sd;
            sd_sync <= sd_meta;
        end
    end

    // ------------------------------------------------------------------
    // Tick and phase are registered together by i2s_clk_gen. The consumer
    // sees the POST-edge phase: odd means the physical BCK rising edge.
    // ------------------------------------------------------------------
    wire sample_en = bck_tick & bck_phase[0];

    // ------------------------------------------------------------------
    // Serial-to-parallel: continuous 16-bit shift register.
    // ------------------------------------------------------------------
    reg [15:0] sr;

    // Channel tag latched at the MSB (bit15) sample instant.
    reg        word_ch;

    // Word completion staging (T/T+1 scheme, see header).
    reg        word_pending;
    reg [15:0] word_data;

    always @(posedge clk_nco or negedge rst_n) begin
        if (!rst_n) begin
            sr           <= 16'd0;
            word_ch      <= 1'b0;
            word_pending <= 1'b0;
            word_data    <= 16'd0;
            pcm_l        <= 16'd0;
            pcm_r        <= 16'd0;
            pcm_valid    <= 1'b0;
        end else begin
            // Default: pcm_valid is a single-cycle pulse.
            pcm_valid <= 1'b0;

            if (sample_en) begin
                // Shift the sampled bit (MSB first, continuous stream).
                sr <= {sr[14:0], sd_sync};

                if (bck_phase == 5'd3) begin
                    // bit15 sample instant: latch the channel level of
                    // the word now being received (LRCK has already
                    // settled to this half frame's level).
                    word_ch <= i2s_lrck;
                end

                if (bck_phase == 5'd1) begin
                    // bit0 sample instant: the shift register now holds
                    // the complete word of the previous half frame.
                    // Stage it; emit on the next clk_nco cycle.
                    word_pending <= 1'b1;
                    word_data    <= {sr[14:0], sd_sync};
                end
            end

            if (word_pending) begin
                word_pending <= 1'b0;
                pcm_valid    <= 1'b1;
                if (word_ch == 1'b0) begin
                    pcm_l <= word_data;   // LRCK low half frame = LEFT
                end else begin
                    pcm_r <= word_data;   // LRCK high half frame = RIGHT
                end
            end
        end
    end

    // ------------------------------------------------------------------
    // Idle detection: transition sensing on every clk_nco edge, tick-
    // quantized timeout of 128 bck_ticks (~45.3 us = 2 LRCK periods,
    // satisfying the ">1 LRCK period" requirement of REQ-REL-003).
    // ------------------------------------------------------------------
    localparam [7:0] IDLE_TICKS_THR = 8'd127;  // 128th quiet tick sets flag

    reg        sd_prev;      // 1-cycle delayed sd_sync for edge detection
    reg  [7:0] idle_ticks;   // count of quiet bck_ticks
    wire       sd_toggle = sd_sync ^ sd_prev;

    always @(posedge clk_nco or negedge rst_n) begin
        if (!rst_n) begin
            sd_prev    <= 1'b0;
            idle_ticks <= 8'd0;
            sd_idle    <= 1'b0;
        end else begin
            sd_prev <= sd_sync;

            if (sd_toggle) begin
                // Any SD activity restarts the timer and clears the flag.
                idle_ticks <= 8'd0;
                sd_idle    <= 1'b0;
            end else if (bck_tick) begin
                if (idle_ticks == IDLE_TICKS_THR) begin
                    // Latched high until the next SD transition.
                    sd_idle <= 1'b1;
                end else begin
                    idle_ticks <= idle_ticks + 8'd1;
                end
            end
        end
    end

endmodule